   272  /* This started like Elf, so check initial fields. */
   273  static int
   274  fill_in_elf_fields(struct elf_header *h,
   275      unsigned *endian,
   276      /*  Size of the object file offsets, not DWARF offset
   277          size. */
   278      unsigned *objoffsetsize,
   279      int *errcode)
   280  {
   281      unsigned locendian = 0;
   282      unsigned locoffsetsize = 0;
   283
   284      switch(h->e_ident[EI_CLASS]) {
   285      case ELFCLASS32:
   286          locoffsetsize = 32;
   287          break;
   288      case ELFCLASS64:
   289          locoffsetsize = 64;
   290          break;
   291      default:
   292          *errcode = DW_DLE_ELF_CLASS_BAD;
   293          return DW_DLV_ERROR;
   294      }
   295      switch(h->e_ident[EI_DATA]) {
   296      case ELFDATA2LSB:
   297          locendian = DW_END_little;
   298          break;
   299      case ELFDATA2MSB:
   300          locendian = DW_END_big;
   301          break;
   302      default:
   303          *errcode = DW_DLE_ELF_ENDIAN_BAD;
   304          return DW_DLV_ERROR;
   305      }
   306      if (h->e_ident[EI_VERSION] != 1 /* EV_CURRENT */) {
   307          *errcode = DW_DLE_ELF_VERSION_BAD;
   308          return DW_DLV_ERROR;
   309      }
   310      *endian = locendian;
   311      *objoffsetsize = locoffsetsize;
   312      return DW_DLV_OK;
   313  }
